import React, { useState } from "react";
import { useParams, useHistory } from "react-router-dom";
import { addUser } from "../../services/ApiUser"; // Adapte le chemin selon ta structure

export default function CardAddAdmin() {
  const { agenceId } = useParams();
  const history = useHistory();

  const [adminData, setAdminData] = useState({
    username: "",
    email: "",
    password: "",
    age: "",
    user_image: null,
  });

  const [errors, setErrors] = useState({});

  const handleChange = (e) => {
    const { name, value } = e.target;
    setAdminData({ ...adminData, [name]: value });
  };

  const handleFileChange = (e) => {
    setAdminData({ ...adminData, user_image: e.target.files[0] });
  };

  const validate = () => {
    let formErrors = {};
    if (!adminData.username.trim()) formErrors.username = "Nom d'utilisateur requis";
    if (!adminData.email.trim()) formErrors.email = "Email requis";
    if (!adminData.password.trim()) formErrors.password = "Mot de passe requis";
    if (!adminData.age || parseInt(adminData.age) < 18 || parseInt(adminData.age) > 100) {
      formErrors.age = "Âge entre 18 et 100 requis";
    }
    if (!adminData.user_image) formErrors.user_image = "Image requise";
    return formErrors;
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    const formErrors = validate();
    if (Object.keys(formErrors).length > 0) {
      setErrors(formErrors);
      return;
    }

    const formData = new FormData();
    Object.keys(adminData).forEach((key) => {
      formData.append(key, adminData[key]);
    });
    formData.append("role", "admin");
    formData.append("agence", agenceId);

    try {
      await addUser(formData);
      alert("Administrateur ajouté avec succès !");
      history.push("/admin/Agence");
    } catch (error) {
      console.error("Erreur lors de l'ajout :", error);
      alert("Erreur lors de l'ajout de l'administrateur.");
    }
  };

  return (
    <div className="relative flex flex-col min-w-0 break-words w-full mb-6 shadow-lg rounded-lg bg-white border-0">
      <div className="rounded-t bg-white mb-0 px-6 py-6">
        <div className="text-center flex justify-between">
          <h6 className="text-gray-700 text-xl font-bold">Ajouter un administrateur</h6>
          <button
            className="bg-blue-500 text-white font-bold uppercase text-xs px-4 py-2 rounded shadow hover:shadow-md"
            type="button"
            onClick={() => history.push("/admin/Agence")}
          >
            Retour
          </button>
        </div>
      </div>

      <div className="flex-auto px-4 lg:px-10 py-10 pt-0">
        <form onSubmit={handleSubmit} encType="multipart/form-data">
          <div className="flex flex-wrap">
            {/* Username */}
            <div className="w-full lg:w-6/12 px-4 mb-4">
              <label className="block text-gray-600 text-xs font-bold mb-2">Nom d'utilisateur</label>
              <input
                type="text"
                name="username"
                value={adminData.username}
                onChange={handleChange}
                className={`px-3 py-3 placeholder-gray-400 text-gray-700 bg-white rounded text-sm shadow w-full ${
                  errors.username ? "border border-red-500" : ""
                }`}
                placeholder="admin123"
              />
              {errors.username && <p className="text-red-500 text-xs mt-1">{errors.username}</p>}
            </div>

            {/* Email */}
            <div className="w-full lg:w-6/12 px-4 mb-4">
              <label className="block text-gray-600 text-xs font-bold mb-2">Email</label>
              <input
                type="email"
                name="email"
                value={adminData.email}
                onChange={handleChange}
                className={`px-3 py-3 placeholder-gray-400 text-gray-700 bg-white rounded text-sm shadow w-full ${
                  errors.email ? "border border-red-500" : ""
                }`}
                placeholder="admin@mail.com"
              />
              {errors.email && <p className="text-red-500 text-xs mt-1">{errors.email}</p>}
            </div>

            {/* Password */}
            <div className="w-full lg:w-6/12 px-4 mb-4">
              <label className="block text-gray-600 text-xs font-bold mb-2">Mot de passe</label>
              <input
                type="password"
                name="password"
                value={adminData.password}
                onChange={handleChange}
                className={`px-3 py-3 placeholder-gray-400 text-gray-700 bg-white rounded text-sm shadow w-full ${
                  errors.password ? "border border-red-500" : ""
                }`}
                placeholder="********"
              />
              {errors.password && <p className="text-red-500 text-xs mt-1">{errors.password}</p>}
            </div>

            {/* Age */}
            <div className="w-full lg:w-6/12 px-4 mb-4">
              <label className="block text-gray-600 text-xs font-bold mb-2">Âge</label>
              <input
                type="number"
                name="age"
                value={adminData.age}
                onChange={handleChange}
                className={`px-3 py-3 placeholder-gray-400 text-gray-700 bg-white rounded text-sm shadow w-full ${
                  errors.age ? "border border-red-500" : ""
                }`}
                placeholder="30"
              />
              {errors.age && <p className="text-red-500 text-xs mt-1">{errors.age}</p>}
            </div>

            {/* Image */}
            <div className="w-full lg:w-12/12 px-4 mb-6">
              <label className="block text-gray-600 text-xs font-bold mb-2">Photo de profil</label>
              <input
                type="file"
                name="user_image"
                onChange={handleFileChange}
                accept="image/*"
                className={`px-3 py-3 text-gray-700 bg-white rounded text-sm shadow w-full ${
                  errors.user_image ? "border border-red-500" : ""
                }`}
              />
              {errors.user_image && <p className="text-red-500 text-xs mt-1">{errors.user_image}</p>}
            </div>
          </div>

          <div className="text-center mt-6">
            <button
              type="submit"
              className="bg-blue-500 text-white font-bold uppercase text-xs px-6 py-3 rounded shadow hover:shadow-md transition duration-150"
            >
              Ajouter l'admin
            </button>
          </div>
        </form>
      </div>
    </div>
  );
}
